<?php declare(strict_types=1); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Elections - E-Voting</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container py-5"><div class="d-flex justify-content-between mb-4"><div><h1 class="h3">Elections</h1><p class="text-secondary">Manage election lifecycle.</p></div><a href="/elections/create" class="btn btn-primary">New Election</a></div><div class="card border-0 shadow-sm rounded-4"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Title</th><th>Type</th><th>Start</th><th>End</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($elections as $e): ?><tr><td class="fw-semibold"><?= htmlspecialchars($e['title'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($e['election_type'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($e['starts_at'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($e['ends_at'], ENT_QUOTES, 'UTF-8') ?></td><td><span class="badge text-bg-secondary"><?= htmlspecialchars($e['status'], ENT_QUOTES, 'UTF-8') ?></span></td><td><?php if (in_array($e['status'], ['scheduled','active'], true)): ?><form method="post" action="/elections/<?= (int)$e['id'] ?>/close"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><button class="btn btn-sm btn-outline-danger">Close</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div><a class="btn btn-link mt-3" href="/dashboard">← Dashboard</a></div></body></html>
